#!/bin/bash
# [체인 87·90, 60 문서] pro6000 → Alpha 결과 회수(작은 파일만). Alpha 에서: bash scripts/pull_chain87.sh
set -e; H=user@train-host; RES=/SPECPHYS_ROOT/_workspace/data/results; mkdir -p $RES/chain87_logs
rsync -az --include='agg_RF_SPEC_D_L*' --include='agg_PM_SPEC_W20_D_L*' --include='agg_RF_SPEC_TAD_L*' --include='agg_RF_SPEC_TAD25_L*' --include='agg_RF_SPEC_TAD_D1_L*' --include='agg_RF_SPEC_D_HW_L*' --include='agg_RF_SPEC_TAD25_HW_L*' --include='agg_RF_SPEC_D_HB_L*' --include='agg_RF_SPEC_TAD25_HB_L*' --include='agg_RF_ENS_DTA_L*' --include='agg_RF_ENS_G_L*' --include='agg_RF_MCDX_D_L*' --include='chain103_*' --include='agg_RF_SPEC_D_L_s[45]00*' --include='agg_RF_SPEC_TA_L_s[45]00*' --include='chain99_*' --include='agg_RF_SPEC_L_s[45]00*' --include='chain100_*' --include='chain97_*' --include='chain95_*' --include='chain94_*' --include='chain92_*' --exclude='*' $H:$RES/ $RES/
rsync -az "$H:/SPECPHYS_TMP/container/chain87_*.log" "$H:/SPECPHYS_TMP/container/chain90_*.log" "$H:/SPECPHYS_TMP/container/chain92_*.log" "$H:/SPECPHYS_TMP/container/chain94_*.log" "$H:/SPECPHYS_TMP/container/chain95_*.log" "$H:/SPECPHYS_TMP/container/chain97_*.log" "$H:/SPECPHYS_TMP/container/chain99_*.log" "$H:/SPECPHYS_TMP/container/chain100_*.log" "$H:/SPECPHYS_TMP/container/chain103_*.log" "$H:/SPECPHYS_TMP/container/ft_RF_SPEC_D_HB_L*.log" "$H:/SPECPHYS_TMP/container/ft_RF_SPEC_TAD25_HB_L*.log" "$H:/SPECPHYS_TMP/container/ft_RF_SPEC_D_HW_L*.log" "$H:/SPECPHYS_TMP/container/ft_RF_SPEC_TAD25_HW_L*.log" $RES/chain87_logs/ 2>/dev/null || true
rsync -az "$H:/SPECPHYS_TMP/container/ft_RF_SPEC_D_L*.log" "$H:/SPECPHYS_TMP/container/ft_PM_SPEC_W20_D_L*.log" "$H:/SPECPHYS_TMP/container/ft_RF_SPEC_TAD_L*.log" $RES/chain87_logs/ 2>/dev/null || true
ls $RES | grep -E "^agg_(RF_SPEC_D|PM_SPEC_W20_D|RF_SPEC_TAD)" | sort; echo PULLED
